query:
ALTER TABLE `contacts` ADD `campaignOffered` varchar(255) AFTER `notes`;
ALTER TABLE `contacts` ADD `offerValue` varchar(100) AFTER `campaignOffered`;
ALTER TABLE `contacts` ADD `listName` varchar(255) AFTER `offerValue`;

ALTER TABLE `sales` ADD `cancelReason` text AFTER `status`;

ALTER TABLE `campaigns` ADD `brand` enum('vodafone','repsol','ambos') DEFAULT 'vodafone' NOT NULL AFTER `product`;

CREATE TABLE `contactOrigins` (
  `id` int AUTO_INCREMENT NOT NULL,
  `name` varchar(100) NOT NULL UNIQUE,
  `createdBy` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  CONSTRAINT `contactOrigins_id` PRIMARY KEY(`id`)
);

INSERT INTO `contactOrigins` (`name`, `createdBy`) VALUES ('Telemarketing', 1), ('Rua', 1), ('Indicação', 1);

CREATE TABLE `energyConfig` (
  `id` int AUTO_INCREMENT NOT NULL,
  `priceKwhSimples` decimal(10,6) NOT NULL DEFAULT 0.1500,
  `priceKwhBiHorariaPonta` decimal(10,6) NOT NULL DEFAULT 0.2000,
  `priceKwhBiHorariaVazio` decimal(10,6) NOT NULL DEFAULT 0.1000,
  `baseDiscountPercent` decimal(5,2) NOT NULL DEFAULT 23.00,
  `vdfClientExtraPercent` decimal(5,2) NOT NULL DEFAULT 2.00,
  `vdfGasClientExtraPercent` decimal(5,2) NOT NULL DEFAULT 3.00,
  `reembolsoPercent` decimal(5,2) NOT NULL DEFAULT 3.00,
  `updatedBy` int,
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `energyConfig_id` PRIMARY KEY(`id`)
);

INSERT INTO `energyConfig` (`priceKwhSimples`, `priceKwhBiHorariaPonta`, `priceKwhBiHorariaVazio`, `baseDiscountPercent`, `vdfClientExtraPercent`, `vdfGasClientExtraPercent`, `reembolsoPercent`) VALUES (0.1500, 0.2000, 0.1000, 23.00, 2.00, 3.00, 3.00);

